#!/usr/bin/env python3
"""Contiguous multi-block scan amortization (cold vs warm BoundaryCache).

Issues overlapping eth_getLogs ranges through a live BoundaryGuard proxy.
Cold: clear cache before every window.
Warm: retain cache across sliding windows that share endpoints.

This is the production-style amortization experiment (not same-message warm-repeat).
"""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import argparse
import json
import time
import urllib.request
from datetime import datetime, timezone
from pathlib import Path

import relayer_proxy_live as harness
from boundaryguard_proxy import ProxyConfig
from hyperlane_identity import DISPATCH_TOPIC, normalize
from strong_accept_suite import CALL_CU, LOG_CU


ROOT = _GITHUB_ROOT
DATA = DATA / "strong_e2e"
OUT = DATA / "contiguous_scan_amortization.json"
MESSAGES = DATA / "hyperlane_messages.jsonl"

OP_CFG = {
    "primary": "https://mainnet.optimism.io",
    "boundary": "https://optimism.drpc.org",
    "repair": "https://op-pokt.nodies.app",
}
ARCHIVE = [
    "https://optimism.drpc.org",
    "https://optimism.gateway.tenderly.co",
    "https://optimism.llamarpc.com",
    "https://optimism-rpc.publicnode.com",
]


def rpc_proxy(url: str, payload: dict, timeout: float = 60.0) -> dict:
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode(),
        headers={"content-type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read())


def pick_span(width: int, windows: int, step: int) -> tuple[str, int, list[tuple[int, int]]]:
    rows = []
    with MESSAGES.open() as handle:
        for line in handle:
            row = json.loads(line)
            if row.get("chain") != "optimism" or not row.get("is_delivered"):
                continue
            rows.append(row)
    rows.sort(key=lambda r: int(r["origin_block_height"]))
    # Prefer mid-history so archive eth_call is available.
    mid = rows[len(rows) // 2]
    mailbox = normalize(mid["origin_mailbox"])
    start = int(mid["origin_block_height"])
    spans = []
    cursor = start
    for _ in range(windows):
        spans.append((cursor, cursor + width - 1))
        cursor += step
    return mailbox, start, spans


def run_phase(proxy_url: str, proxy, mailbox: str, spans: list[tuple[int, int]], *, clear_each: bool) -> dict:
    stats0 = dict(proxy.stats)
    t0 = time.time()
    completed = 0
    fail = 0
    for start, end in spans:
        if clear_each:
            proxy.cache.clear()
        payload = {
            "jsonrpc": "2.0",
            "id": 1,
            "method": "eth_getLogs",
            "params": [
                {
                    "fromBlock": hex(start),
                    "toBlock": hex(end),
                    "address": mailbox,
                    "topics": [DISPATCH_TOPIC],
                }
            ],
        }
        try:
            resp = rpc_proxy(proxy_url, payload, timeout=90.0)
            if "error" in resp:
                fail += 1
            else:
                completed += 1
        except Exception:
            fail += 1
    stats1 = dict(proxy.stats)
    delta = {k: stats1.get(k, 0) - stats0.get(k, 0) for k in stats0}
    cu = (
        delta.get("audited", 0) * LOG_CU
        + delta.get("boundary_calls", 0) * CALL_CU
        + delta.get("repair_calls", 0) * LOG_CU
    )
    return {
        "windows": len(spans),
        "completed": completed,
        "fail_closed_or_error": fail,
        "elapsed_s": time.time() - t0,
        "proxy_delta": delta,
        "cu_est": cu,
        "boundary_calls": delta.get("boundary_calls", 0),
        "clear_each": clear_each,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--width", type=int, default=200)
    parser.add_argument("--windows", type=int, default=8)
    parser.add_argument("--step", type=int, default=100, help="Sliding step; <width ⇒ shared ends")
    parser.add_argument("--port", type=int, default=18611)
    args = parser.parse_args()

    DATA.mkdir(parents=True, exist_ok=True)
    mailbox, base, spans = pick_span(args.width, args.windows, args.step)
    cfg = ProxyConfig(
        chain_id="optimism",
        mailbox=mailbox,
        primary_url=OP_CFG["primary"],
        boundary_url=ARCHIVE[0],
        repair_url=OP_CFG["repair"],
        boundary_urls=ARCHIVE[1:],
        timeout_s=25.0,
        retry_count=1,
        chunk_count=4,
        confirmation_depth=0,
        trace_path=str(DATA / "contiguous_scan_proxy_trace.jsonl"),
    )
    trace = Path(cfg.trace_path)
    if trace.exists():
        trace.unlink()
    server, proxy = harness.start_proxy(cfg, args.port)
    proxy_url = f"http://127.0.0.1:{args.port}"
    try:
        print("spans", spans[:3], "...", spans[-1], flush=True)
        proxy.cache.clear()
        cold = run_phase(proxy_url, proxy, mailbox, spans, clear_each=True)
        print("cold", cold, flush=True)
        proxy.cache.clear()
        warm = run_phase(proxy_url, proxy, mailbox, spans, clear_each=False)
        print("warm", warm, flush=True)
    finally:
        server.shutdown()

    saving = None
    if cold["boundary_calls"]:
        saving = 100.0 * (cold["boundary_calls"] - warm["boundary_calls"]) / cold["boundary_calls"]
    cu_saving = None
    if cold["cu_est"]:
        cu_saving = 100.0 * (cold["cu_est"] - warm["cu_est"]) / cold["cu_est"]
    out = {
        "gate": "contiguous_scan_amortization",
        "provenance": "live_public_rpc_observation",
        "observed_at": datetime.now(timezone.utc).isoformat(),
        "chain": "optimism",
        "mailbox": mailbox,
        "width": args.width,
        "windows": args.windows,
        "step": args.step,
        "spans": [{"start": a, "end": b} for a, b in spans],
        "cold_clear_each_window": cold,
        "warm_retain_cache": warm,
        "boundary_call_saving_pct": saving,
        "cu_saving_pct": cu_saving,
        "pass": bool(
            cold["completed"] >= args.windows * 0.75
            and warm["completed"] >= args.windows * 0.75
            and warm["boundary_calls"] < cold["boundary_calls"]
        ),
        "note": "Sliding windows share endpoints; warm path reuses BoundaryCache.",
    }
    OUT.write_text(json.dumps(out, indent=2, sort_keys=True) + "\n")
    print(json.dumps({k: out[k] for k in out if k != "spans"}, indent=2, sort_keys=True))
    raise SystemExit(0 if out["pass"] else 2)


if __name__ == "__main__":
    main()
